// INPUT VALIDATION & STANDARDIZATION
const inputData = $input.first().json;
const requestData = inputData.body || inputData;

// Validate required fields
if (!requestData.domain) {
  throw new Error('Domain is required');
}

// Clean and normalize domain
const domain = requestData.domain.toLowerCase().trim().replace(/^https?:\/\//, '').replace(/\/.*$/, '');

// Optional: first name, last name, or list of names for permutations
const firstName = requestData.firstName || '';
const lastName = requestData.lastName || '';
const nameList = requestData.nameList || [];

// Configuration options
const options = {
  maxPermutations: requestData.maxPermutations || 50,
  verificationDepth: requestData.verificationDepth || 'full', // 'quick' or 'full'
  includeCommonPatterns: requestData.includeCommonPatterns !== false,
  skipSpamTrapCheck: requestData.skipSpamTrapCheck || false
};

return [{
  json: {
    domain: domain,
    firstName: firstName,
    lastName: lastName,
    nameList: nameList,
    options: options,
    requestId: `req_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    timestamp: new Date().toISOString()
  }
}];

// EMAIL PERMUTATION GENERATOR
const data = $input.first().json;
const { domain, firstName, lastName, nameList, options } = data;

// Common email patterns
const patterns = [
  // Name-based patterns
  '{first}.{last}',
  '{first}{last}',
  '{first}_{last}',
  '{first}-{last}',
  '{last}.{first}',
  '{last}{first}',
  '{f}{last}',
  '{first}{l}',
  '{f}.{last}',
  '{first}.{l}',
  '{first}',
  '{last}',
  // Common generic patterns
  'info',
  'contact',
  'hello',
  'support',
  'sales',
  'admin',
  'office',
  'team',
  'help',
  'service'
];

const permutations = [];

// Generate permutations from provided names
function generateFromNames(first, last) {
  if (!first && !last) return [];

  const f = first.toLowerCase().trim();
  const l = last.toLowerCase().trim();
  const generated = [];

  patterns.forEach(pattern => {
    if (pattern.includes('{')) {
      let email = pattern
        .replace('{first}', f)
        .replace('{last}', l)
        .replace('{f}', f.charAt(0))
        .replace('{l}', l.charAt(0));

      // Only add if all placeholders were replaced
      if (!email.includes('{') && email.length > 0) {
        generated.push(`${email}@${domain}`);
      }
    } else {
      generated.push(`${pattern}@${domain}`);
    }
  });

  return generated;
}

// Generate from firstName and lastName if provided
if (firstName || lastName) {
  permutations.push(...generateFromNames(firstName, lastName));
}

// Generate from nameList if provided
if (nameList && Array.isArray(nameList) && nameList.length > 0) {
  nameList.forEach(nameObj => {
    const first = nameObj.firstName || '';
    const last = nameObj.lastName || '';
    permutations.push(...generateFromNames(first, last));
  });
}

// Add common generic emails if no names provided or if option enabled
if (options.includeCommonPatterns || permutations.length === 0) {
  const genericPatterns = ['info', 'contact', 'hello', 'support', 'sales', 'admin', 'office', 'team', 'help', 'service'];
  genericPatterns.forEach(pattern => {
    permutations.push(`${pattern}@${domain}`);
  });
}

// Remove duplicates and limit to maxPermutations
const uniquePermutations = [...new Set(permutations)].slice(0, options.maxPermutations);

return [{
  json: {
    ...data,
    permutations: uniquePermutations,
    totalPermutations: uniquePermutations.length,
    generatedAt: new Date().toISOString()
  }
}];

// HUNTER-STYLE PATTERN DETECTION
const data = $input.first().json;
const { domain, permutations } = data;

// Pattern detection analyzes common email formats for the domain
// This would typically involve:
// 1. Known pattern database lookup
// 2. Historical validation data
// 3. Industry-standard patterns

const patternAnalysis = {
  domain: domain,
  detectedPatterns: [],
  confidence: 'medium',
  patternScore: 0.5
};

// Analyze permutation patterns
const patternFrequency = {};

permutations.forEach(email => {
  const localPart = email.split('@')[0];

  // Detect pattern type
  let patternType = 'unknown';

  if (localPart.includes('.')) {
    patternType = 'dot_separated';
  } else if (localPart.includes('_')) {
    patternType = 'underscore_separated';
  } else if (localPart.includes('-')) {
    patternType = 'hyphen_separated';
  } else if (['info', 'contact', 'hello', 'support', 'sales', 'admin', 'office', 'team', 'help', 'service'].includes(localPart)) {
    patternType = 'generic';
  } else if (localPart.length <= 2) {
    patternType = 'initials';
  } else {
    patternType = 'concatenated';
  }

  patternFrequency[patternType] = (patternFrequency[patternType] || 0) + 1;
});

// Determine most likely patterns
const sortedPatterns = Object.entries(patternFrequency)
  .sort((a, b) => b[1] - a[1])
  .map(([pattern, count]) => ({
    pattern: pattern,
    count: count,
    percentage: ((count / permutations.length) * 100).toFixed(2)
  }));

patternAnalysis.detectedPatterns = sortedPatterns;

// Set confidence based on pattern clarity
if (sortedPatterns.length > 0 && parseFloat(sortedPatterns[0].percentage) > 40) {
  patternAnalysis.confidence = 'high';
  patternAnalysis.patternScore = 0.8;
} else if (sortedPatterns.length > 0 && parseFloat(sortedPatterns[0].percentage) > 20) {
  patternAnalysis.confidence = 'medium';
  patternAnalysis.patternScore = 0.5;
} else {
  patternAnalysis.confidence = 'low';
  patternAnalysis.patternScore = 0.3;
}

// Prioritize permutations based on pattern analysis
const prioritizedPermutations = permutations.map(email => {
  const localPart = email.split('@')[0];
  let priority = 5; // default medium priority

  // Higher priority for detected common patterns
  if (localPart.includes('.') && sortedPatterns[0]?.pattern === 'dot_separated') {
    priority = 9;
  } else if (['info', 'contact', 'hello', 'support'].includes(localPart)) {
    priority = 8;
  } else if (localPart.includes('_') && sortedPatterns[0]?.pattern === 'underscore_separated') {
    priority = 7;
  }

  return {
    email: email,
    priority: priority,
    pattern: localPart.includes('.') ? 'dot_separated' : 
             localPart.includes('_') ? 'underscore_separated' :
             localPart.includes('-') ? 'hyphen_separated' : 'concatenated'
  };
}).sort((a, b) => b.priority - a.priority);

return [{
  json: {
    ...data,
    patternAnalysis: patternAnalysis,
    prioritizedPermutations: prioritizedPermutations,
    patternDetectionComplete: true
  }
}];

// DNS MX RECORD LOOKUP & VALIDATION
const data = $input.first().json;
const { domain } = data;
const dns = require('dns').promises;

let mxRecords = [];
let mxLookupSuccess = false;
let mxError = null;

try {
  // Perform MX record lookup
  const records = await dns.resolveMx(domain);
  mxRecords = records.sort((a, b) => a.priority - b.priority);
  mxLookupSuccess = true;

  console.log(`MX Records found for ${domain}:`, mxRecords);
} catch (error) {
  mxError = error.message;
  console.error(`MX lookup failed for ${domain}:`, error.message);

  // If MX lookup fails, domain likely doesn't accept email
  mxLookupSuccess = false;
}

// Analyze MX configuration
const mxAnalysis = {
  hasMX: mxLookupSuccess,
  mxCount: mxRecords.length,
  primaryMX: mxRecords[0]?.exchange || null,
  mxRecords: mxRecords,
  error: mxError,
  acceptsEmail: mxLookupSuccess,
  mxScore: mxLookupSuccess ? 1.0 : 0.0
};

// Detect mail provider type
if (mxRecords.length > 0) {
  const primaryMX = mxRecords[0].exchange.toLowerCase();

  if (primaryMX.includes('google') || primaryMX.includes('gmail')) {
    mxAnalysis.provider = 'Google Workspace';
    mxAnalysis.providerReliability = 'high';
  } else if (primaryMX.includes('outlook') || primaryMX.includes('microsoft') || primaryMX.includes('office365')) {
    mxAnalysis.provider = 'Microsoft 365';
    mxAnalysis.providerReliability = 'high';
  } else if (primaryMX.includes('zoho')) {
    mxAnalysis.provider = 'Zoho Mail';
    mxAnalysis.providerReliability = 'medium';
  } else if (primaryMX.includes('protonmail')) {
    mxAnalysis.provider = 'ProtonMail';
    mxAnalysis.providerReliability = 'high';
  } else {
    mxAnalysis.provider = 'Custom/Unknown';
    mxAnalysis.providerReliability = 'medium';
  }
}

return [{
  json: {
    ...data,
    mxAnalysis: mxAnalysis,
    mxLookupComplete: true
  }
}];

// SMTP VERIFICATION SIMULATION
// Note: Full SMTP verification requires actual SMTP connection
// This implementation provides verification logic structure

const data = $input.first().json;
const { prioritizedPermutations, mxAnalysis, options } = data;

// If no MX records, all emails are invalid
if (!mxAnalysis.hasMX) {
  const verifiedEmails = prioritizedPermutations.map(item => ({
    email: item.email,
    smtpVerified: false,
    smtpResponse: 'No MX records found',
    smtpCode: null,
    deliverable: false,
    verificationMethod: 'mx_check'
  }));

  return [{
    json: {
      ...data,
      verifiedEmails: verifiedEmails,
      smtpVerificationComplete: true
    }
  }];
}

// Simulate SMTP verification process
// In production, this would connect to SMTP server and verify each email
const verifiedEmails = prioritizedPermutations.map(item => {
  const email = item.email;

  // Simulation logic for different email types
  let smtpVerified = false;
  let smtpResponse = '';
  let smtpCode = null;
  let deliverable = false;

  // Simulate verification based on pattern and common knowledge
  const localPart = email.split('@')[0];

  // Generic emails (info, contact, etc.) typically exist
  if (['info', 'contact', 'hello', 'support', 'sales'].includes(localPart)) {
    smtpVerified = true;
    smtpResponse = '250 OK';
    smtpCode = 250;
    deliverable = true;
  } 
  // Random/complex patterns - uncertain
  else if (localPart.length > 20 || localPart.match(/[0-9]{3,}/)) {
    smtpVerified = false;
    smtpResponse = '550 User not found';
    smtpCode = 550;
    deliverable = false;
  }
  // Standard name patterns - likely valid but uncertain without real verification
  else {
    // Simulate 60% success rate for name-based patterns
    const random = Math.random();
    if (random > 0.4) {
      smtpVerified = true;
      smtpResponse = '250 OK';
      smtpCode = 250;
      deliverable = true;
    } else {
      smtpVerified = false;
      smtpResponse = '550 User not found';
      smtpCode = 550;
      deliverable = false;
    }
  }

  return {
    email: email,
    priority: item.priority,
    pattern: item.pattern,
    smtpVerified: smtpVerified,
    smtpResponse: smtpResponse,
    smtpCode: smtpCode,
    deliverable: deliverable,
    verificationMethod: 'smtp_simulation',
    verifiedAt: new Date().toISOString()
  };
});

// Note about production implementation
const verificationNote = {
  message: 'SMTP verification simulated. In production, integrate with email verification API (Hunter.io, ZeroBounce, NeverBounce, etc.) for real SMTP handshake verification.',
  recommendedAPIs: ['Hunter.io', 'ZeroBounce', 'NeverBounce', 'Clearout', 'EmailListVerify'],
  realSMTPRequired: true
};

return [{
  json: {
    ...data,
    verifiedEmails: verifiedEmails,
    verificationNote: verificationNote,
    smtpVerificationComplete: true
  }
}];

// CATCH-ALL DETECTION
const data = $input.first().json;
const { domain, mxAnalysis } = data;
const dns = require('dns').promises;

let isCatchAll = false;
let catchAllConfidence = 'low';
let catchAllScore = 0.0;
let catchAllMethod = 'none';
let catchAllDetails = {};

// Method 1: Test with random/invalid email
try {
  // In a real implementation, we would send SMTP RCPT TO command with a random email
  // If it accepts, the domain is likely catch-all

  const randomEmail = `test-${Math.random().toString(36).substr(2, 15)}@${domain}`;

  // Simulated catch-all detection
  // In production, send SMTP verification to obviously fake email
  // If server responds 250 OK, it's catch-all

  // For simulation purposes, let's check based on MX provider
  if (mxAnalysis.provider === 'Google Workspace' || mxAnalysis.provider === 'Microsoft 365') {
    // Major providers typically don't use catch-all
    isCatchAll = false;
    catchAllConfidence = 'high';
    catchAllScore = 0.1;
    catchAllMethod = 'provider_analysis';
    catchAllDetails = {
      provider: mxAnalysis.provider,
      reasoning: 'Major email providers (Google, Microsoft) typically disable catch-all by default'
    };
  } else {
    // Unknown providers - medium uncertainty
    // Would need actual SMTP test
    isCatchAll = false;
    catchAllConfidence = 'medium';
    catchAllScore = 0.3;
    catchAllMethod = 'heuristic';
    catchAllDetails = {
      provider: mxAnalysis.provider || 'Unknown',
      reasoning: 'Catch-all status uncertain without SMTP verification',
      recommendation: 'Perform actual SMTP verification with random email address'
    };
  }

} catch (error) {
  console.error('Catch-all detection error:', error.message);
  catchAllDetails.error = error.message;
}

// Method 2: Check for wildcard MX patterns (less reliable)
if (mxAnalysis.mxRecords && mxAnalysis.mxRecords.length > 0) {
  const mxHosts = mxAnalysis.mxRecords.map(r => r.exchange);

  // Some catch-all indicators in MX configuration
  const catchAllIndicators = ['mail', 'mx', 'smtp', 'email'];
  const hasIndicators = mxHosts.some(host => 
    catchAllIndicators.some(indicator => host.toLowerCase().includes(indicator))
  );

  if (hasIndicators && catchAllConfidence === 'low') {
    catchAllConfidence = 'medium';
  }
}

const catchAllAnalysis = {
  isCatchAll: isCatchAll,
  confidence: catchAllConfidence,
  score: catchAllScore,
  method: catchAllMethod,
  details: catchAllDetails,
  impact: isCatchAll ? 'All email addresses will appear valid on SMTP check' : 'Email verification results are reliable',
  recommendation: isCatchAll ? 'Use additional verification methods (email opens, clicks, etc.)' : 'Standard verification is sufficient'
};

return [{
  json: {
    ...data,
    catchAllAnalysis: catchAllAnalysis,
    catchAllDetectionComplete: true
  }
}];

// SPAM TRAP DETECTION
const data = $input.first().json;
const { verifiedEmails, domain, options } = data;

// Skip if requested
if (options.skipSpamTrapCheck) {
  return [{
    json: {
      ...data,
      spamTrapAnalysis: {
        skipped: true,
        reason: 'User requested to skip spam trap check'
      },
      spamTrapDetectionComplete: true
    }
  }];
}

// Known spam trap patterns and indicators
const spamTrapPatterns = [
  /^abuse@/i,
  /^spam@/i,
  /^trap@/i,
  /^honeypot@/i,
  /^test[0-9]+@/i,
  /^noreply@/i,
  /^no-reply@/i,
  /^donotreply@/i,
  /^postmaster@/i
];

// Known spam trap domains (sample list)
const knownSpamTrapDomains = [
  'spamtrap.com',
  'honeypot.email',
  'trap.example.com',
  'blacklist.test'
];

// Analyze each email for spam trap indicators
const emailsWithSpamTrapAnalysis = verifiedEmails.map(item => {
  const email = item.email;
  let isSpamTrap = false;
  let spamTrapRisk = 'low';
  let spamTrapIndicators = [];

  // Check 1: Pattern matching
  spamTrapPatterns.forEach(pattern => {
    if (pattern.test(email)) {
      isSpamTrap = true;
      spamTrapRisk = 'high';
      spamTrapIndicators.push(`Matches spam trap pattern: ${pattern}`);
    }
  });

  // Check 2: Known spam trap domains
  if (knownSpamTrapDomains.includes(domain.toLowerCase())) {
    isSpamTrap = true;
    spamTrapRisk = 'high';
    spamTrapIndicators.push('Domain is known spam trap');
  }

  // Check 3: Suspicious patterns
  const localPart = email.split('@')[0];

  // Very old/abandoned looking emails
  if (localPart.match(/^[a-z]$/i)) {
    spamTrapRisk = 'medium';
    spamTrapIndicators.push('Single character email (could be recycled/trap)');
  }

  // Random character sequences
  if (localPart.match(/^[a-z]{20,}$/i) || localPart.match(/^[0-9]{10,}$/)) {
    spamTrapRisk = 'medium';
    spamTrapIndicators.push('Unusual character pattern');
  }

  // Common administrative emails that might be traps
  const adminEmails = ['webmaster', 'admin', 'administrator', 'hostmaster'];
  if (adminEmails.includes(localPart.toLowerCase())) {
    spamTrapRisk = 'low';
    spamTrapIndicators.push('Administrative email - use with caution');
  }

  return {
    ...item,
    spamTrap: {
      isSpamTrap: isSpamTrap,
      risk: spamTrapRisk,
      indicators: spamTrapIndicators,
      safe: !isSpamTrap && spamTrapRisk === 'low'
    }
  };
});

// Overall spam trap analysis
const spamTrapAnalysis = {
  totalEmails: emailsWithSpamTrapAnalysis.length,
  spamTraps: emailsWithSpamTrapAnalysis.filter(e => e.spamTrap.isSpamTrap).length,
  highRisk: emailsWithSpamTrapAnalysis.filter(e => e.spamTrap.risk === 'high').length,
  mediumRisk: emailsWithSpamTrapAnalysis.filter(e => e.spamTrap.risk === 'medium').length,
  safe: emailsWithSpamTrapAnalysis.filter(e => e.spamTrap.safe).length,
  domainRisk: knownSpamTrapDomains.includes(domain.toLowerCase()) ? 'high' : 'low',
  recommendation: emailsWithSpamTrapAnalysis.filter(e => e.spamTrap.isSpamTrap).length > 0 
    ? 'Remove identified spam traps before sending' 
    : 'Domain appears safe for email outreach'
};

return [{
  json: {
    ...data,
    verifiedEmails: emailsWithSpamTrapAnalysis,
    spamTrapAnalysis: spamTrapAnalysis,
    spamTrapDetectionComplete: true
  }
}];

// CONFIDENCE SCORING ENGINE
const data = $input.first().json;
const { verifiedEmails, mxAnalysis, catchAllAnalysis, patternAnalysis } = data;

// Scoring weights
const weights = {
  smtpVerification: 0.35,      // 35% - Most important
  mxRecords: 0.20,              // 20% - Domain accepts email
  patternMatch: 0.15,           // 15% - Matches common patterns
  catchAllPenalty: 0.15,        // 15% - Catch-all reduces confidence
  spamTrapPenalty: 0.10,        // 10% - Spam trap risk
  providerReliability: 0.05     // 5% - Email provider quality
};

// Score each email
const scoredEmails = verifiedEmails.map(item => {
  let score = 0;
  const scoreBreakdown = {};

  // 1. SMTP Verification Score (35%)
  if (item.smtpVerified && item.deliverable) {
    scoreBreakdown.smtp = weights.smtpVerification;
    score += weights.smtpVerification;
  } else {
    scoreBreakdown.smtp = 0;
  }

  // 2. MX Records Score (20%)
  if (mxAnalysis.hasMX) {
    scoreBreakdown.mx = weights.mxRecords;
    score += weights.mxRecords;
  } else {
    scoreBreakdown.mx = 0;
  }

  // 3. Pattern Match Score (15%)
  if (item.priority >= 8) {
    scoreBreakdown.pattern = weights.patternMatch;
    score += weights.patternMatch;
  } else if (item.priority >= 5) {
    scoreBreakdown.pattern = weights.patternMatch * 0.5;
    score += weights.patternMatch * 0.5;
  } else {
    scoreBreakdown.pattern = 0;
  }

  // 4. Catch-All Penalty (15%)
  if (catchAllAnalysis.isCatchAll) {
    scoreBreakdown.catchAll = -weights.catchAllPenalty;
    score -= weights.catchAllPenalty;
  } else {
    scoreBreakdown.catchAll = weights.catchAllPenalty * (1 - catchAllAnalysis.score);
    score += weights.catchAllPenalty * (1 - catchAllAnalysis.score);
  }

  // 5. Spam Trap Penalty (10%)
  if (item.spamTrap.isSpamTrap) {
    scoreBreakdown.spamTrap = -weights.spamTrapPenalty;
    score -= weights.spamTrapPenalty;
  } else if (item.spamTrap.risk === 'high') {
    scoreBreakdown.spamTrap = -weights.spamTrapPenalty * 0.8;
    score -= weights.spamTrapPenalty * 0.8;
  } else if (item.spamTrap.risk === 'medium') {
    scoreBreakdown.spamTrap = -weights.spamTrapPenalty * 0.4;
    score -= weights.spamTrapPenalty * 0.4;
  } else {
    scoreBreakdown.spamTrap = weights.spamTrapPenalty;
    score += weights.spamTrapPenalty;
  }

  // 6. Provider Reliability Score (5%)
  if (mxAnalysis.providerReliability === 'high') {
    scoreBreakdown.provider = weights.providerReliability;
    score += weights.providerReliability;
  } else if (mxAnalysis.providerReliability === 'medium') {
    scoreBreakdown.provider = weights.providerReliability * 0.5;
    score += weights.providerReliability * 0.5;
  } else {
    scoreBreakdown.provider = 0;
  }

  // Normalize score to 0-100
  const confidenceScore = Math.max(0, Math.min(100, score * 100));

  // Determine confidence level
  let confidenceLevel = 'low';
  if (confidenceScore >= 75) {
    confidenceLevel = 'high';
  } else if (confidenceScore >= 45) {
    confidenceLevel = 'medium';
  }

  return {
    ...item,
    confidence: {
      score: Math.round(confidenceScore),
      level: confidenceLevel,
      breakdown: scoreBreakdown,
      factors: {
        smtpVerified: item.smtpVerified,
        hasMX: mxAnalysis.hasMX,
        patternPriority: item.priority,
        isCatchAll: catchAllAnalysis.isCatchAll,
        spamTrapRisk: item.spamTrap.risk,
        provider: mxAnalysis.provider
      }
    }
  };
});

// Overall scoring summary
const scoringSummary = {
  totalEmails: scoredEmails.length,
  averageScore: Math.round(
    scoredEmails.reduce((sum, e) => sum + e.confidence.score, 0) / scoredEmails.length
  ),
  highConfidence: scoredEmails.filter(e => e.confidence.level === 'high').length,
  mediumConfidence: scoredEmails.filter(e => e.confidence.level === 'medium').length,
  lowConfidence: scoredEmails.filter(e => e.confidence.level === 'low').length,
  scoringWeights: weights
};

return [{
  json: {
    ...data,
    verifiedEmails: scoredEmails,
    scoringSummary: scoringSummary,
    confidenceScoringComplete: true
  }
}];

// EMAIL CLASSIFICATION ENGINE
const data = $input.first().json;
const { verifiedEmails, domain, scoringSummary } = data;

// Classification rules:
// VALID: High confidence (75+), SMTP verified, no spam trap, deliverable
// RISKY: Medium confidence (45-74), uncertain verification, or catch-all domain
// INVALID: Low confidence (<45), failed SMTP, spam trap, or no MX records

const classifiedEmails = verifiedEmails.map(item => {
  let classification = 'INVALID';
  let reasons = [];
  let recommendation = '';

  const score = item.confidence.score;
  const { smtpVerified, deliverable } = item;
  const { isSpamTrap, risk } = item.spamTrap;

  // VALID Classification
  if (score >= 75 && smtpVerified && deliverable && !isSpamTrap && risk !== 'high') {
    classification = 'VALID';
    reasons.push('High confidence score');
    reasons.push('SMTP verified');
    reasons.push('Deliverable');
    reasons.push('No spam trap indicators');
    recommendation = 'Safe to use for email outreach';
  }
  // RISKY Classification  
  else if (score >= 45 || (smtpVerified && risk === 'medium')) {
    classification = 'RISKY';

    if (score >= 45 && score < 75) reasons.push('Medium confidence score');
    if (!smtpVerified) reasons.push('SMTP verification uncertain');
    if (risk === 'medium') reasons.push('Medium spam trap risk');
    if (item.confidence.factors.isCatchAll) reasons.push('Catch-all domain');

    recommendation = 'Use with caution. Consider additional verification or warm-up sending.';
  }
  // INVALID Classification
  else {
    classification = 'INVALID';

    if (score < 45) reasons.push('Low confidence score');
    if (!smtpVerified || !deliverable) reasons.push('SMTP verification failed');
    if (isSpamTrap) reasons.push('Identified as spam trap');
    if (risk === 'high') reasons.push('High spam trap risk');
    if (!item.confidence.factors.hasMX) reasons.push('No MX records');

    recommendation = 'Do not use. High risk of bounce or spam complaints.';
  }

  return {
    email: item.email,
    classification: classification,
    confidence: item.confidence,
    reasons: reasons,
    recommendation: recommendation,
    metadata: {
      pattern: item.pattern,
      priority: item.priority,
      smtpVerified: item.smtpVerified,
      deliverable: item.deliverable,
      spamTrapRisk: item.spamTrap.risk,
      verifiedAt: item.verifiedAt
    }
  };
});

// Sort by classification and confidence score
const sortedClassified = classifiedEmails.sort((a, b) => {
  const order = { 'VALID': 3, 'RISKY': 2, 'INVALID': 1 };
  if (order[a.classification] !== order[b.classification]) {
    return order[b.classification] - order[a.classification];
  }
  return b.confidence.score - a.confidence.score;
});

// Classification summary
const classificationSummary = {
  total: classifiedEmails.length,
  valid: classifiedEmails.filter(e => e.classification === 'VALID').length,
  risky: classifiedEmails.filter(e => e.classification === 'RISKY').length,
  invalid: classifiedEmails.filter(e => e.classification === 'INVALID').length,
  validRate: ((classifiedEmails.filter(e => e.classification === 'VALID').length / classifiedEmails.length) * 100).toFixed(2) + '%',
  riskyRate: ((classifiedEmails.filter(e => e.classification === 'RISKY').length / classifiedEmails.length) * 100).toFixed(2) + '%',
  invalidRate: ((classifiedEmails.filter(e => e.classification === 'INVALID').length / classifiedEmails.length) * 100).toFixed(2) + '%'
};

return [{
  json: {
    domain: domain,
    classifiedEmails: sortedClassified,
    classificationSummary: classificationSummary,
    scoringSummary: scoringSummary,
    validEmails: sortedClassified.filter(e => e.classification === 'VALID'),
    riskyEmails: sortedClassified.filter(e => e.classification === 'RISKY'),
    invalidEmails: sortedClassified.filter(e => e.classification === 'INVALID'),
    completedAt: new Date().toISOString(),
    success: true
  }
}];

// FINAL RESPONSE FORMATTER
const data = $input.first().json;

// Create comprehensive response
const response = {
  success: data.success,
  requestId: data.requestId,
  domain: data.domain,
  timestamp: new Date().toISOString(),

  summary: {
    totalEmailsAnalyzed: data.classificationSummary.total,
    validEmails: data.classificationSummary.valid,
    riskyEmails: data.classificationSummary.risky,
    invalidEmails: data.classificationSummary.invalid,
    validRate: data.classificationSummary.validRate,
    averageConfidence: data.scoringSummary.averageScore
  },

  results: {
    valid: data.validEmails.map(e => ({
      email: e.email,
      confidence: e.confidence.score,
      recommendation: e.recommendation
    })),
    risky: data.riskyEmails.map(e => ({
      email: e.email,
      confidence: e.confidence.score,
      reasons: e.reasons,
      recommendation: e.recommendation
    })),
    invalid: data.invalidEmails.map(e => ({
      email: e.email,
      confidence: e.confidence.score,
      reasons: e.reasons
    }))
  },

  detailedAnalysis: {
    mxRecords: data.mxAnalysis,
    patternAnalysis: data.patternAnalysis,
    catchAllDetection: data.catchAllAnalysis,
    spamTrapAnalysis: data.spamTrapAnalysis
  },

  allEmails: data.classifiedEmails,

  metadata: {
    verificationNote: data.verificationNote,
    processingTime: 'Completed',
    apiVersion: '1.0',
    workflowName: 'Email Enrichment Layer'
  }
};

return [{ json: response }];
